  void _logout() async {
    // if (_shouldDisableAutoSyncOnLogOut) {
    //   // disable auto sync if it was enabled only when loading wallet
    ref.read(pWallets).getWallet(walletId).shouldAutoSync = false;
    // }

    ref.read(currentWalletIdProvider.notifier).state = null;
    ref.read(transactionFilterProvider.state).state = null;
    if (ref.read(prefsChangeNotifierProvider).isAutoBackupEnabled &&
        ref.read(prefsChangeNotifierProvider).backupFrequencyType ==
            BackupFrequencyType.afterClosingAWallet) {
      unawaited(ref.read(autoSWBServiceProvider).doBackup());
    }

    // Close the wallet according to syncing preferences.
    switch (ref.read(prefsChangeNotifierProvider).syncType) {
      case SyncingType.currentWalletOnly:
        // Close the wallet.
        unawaited(ref.watch(pWallets).getWallet(walletId).exit());
      // unawaited so we don't lag the UI.
      case SyncingType.selectedWalletsAtStartup:
        // Close if this wallet is not in the list to be synced.
        if (!ref
            .read(prefsChangeNotifierProvider)
            .walletIdsSyncOnStartup
            .contains(widget.walletId)) {
          unawaited(ref.watch(pWallets).getWallet(walletId).exit());
          // unawaited so we don't lag the UI.
        }
      case SyncingType.allWalletsOnStartup:
        // Do nothing.
        break;
    }
  }

  /// [ink] is the hero's ink, because this glyph sits on the hero.
  ///
  /// It used to take the theme's status colours, which are chosen against the
  /// page background. On the hero they land on the coin's own colour: the green
  /// "synced" glyph measured 1.05:1 on Pepecoin's green and 1.44:1 on BFX's
  /// blue — the button was there, but on neither coin could you see it.
  ///
  /// Recolouring the status hue to reach contrast was tried and rejected: it
  /// only clears on a mid-tone hero by going dark, which turns green into
  /// #005349 mud beside the white bell and menu, and on blue it turns the
  /// offline red into a pale pink that reads as anything but a warning.
  ///
  /// So the glyph follows the rule the rest of the hero already follows —
  /// heroInk, the same white the bell and menu beside it use. No state is lost
  /// to this: each status draws a *different glyph* (radio, radioSyncing,
  /// radioProblem), and the chip directly below spells the state out in words.
  /// The sync state, as a glyph and a colour.
  ///
  /// It used to be signal bars. Those are the phone's reception icon, and on a
  /// screen that is not about reception they read as "your mobile signal",
  /// which is a thing this app neither measures nor can affect. What the
  /// control actually reports is whether the wallet is caught up with its
  /// node, so it says that: a tick when it is, a warning when it could not be.
  ///
  /// Shape and colour both carry the state, never colour alone. Measured on
  /// the button's own disc, which is white in the light theme and #1A2130 in
  /// the dark one, against the 3:1 floor that applies to a glyph:
  ///
  ///     green  light 3.25:1   dark 7.57:1
  ///     red    light 4.22:1   dark 3.90:1
  ///
  /// Syncing stays in the ordinary bar ink rather than taking the theme's
  /// amber, which measures 1.32:1 on the light page and would be a warning
  /// nobody could see. It is the transient state and the rotating glyph
  /// already names it; green and red are the two worth colouring.
  Widget _buildNetworkIcon(WalletSyncStatus status, Color ink) {
    final colors = Theme.of(context).extension<StackColors>()!;
    switch (status) {
      case WalletSyncStatus.unableToSync:
        return adaptiveIcon(
          Assets.svg.alertCircle,
          CupertinoIcons.exclamationmark_circle,
          size: 20,
          color: colors.accentColorRed,
        );
      case WalletSyncStatus.synced:
        return adaptiveIcon(
          Assets.svg.checkCircle,
          CupertinoIcons.check_mark_circled,
          size: 20,
          color: colors.accentColorGreen,
        );
      case WalletSyncStatus.syncing:
        return adaptiveIcon(
          Assets.svg.arrowRotate,
          CupertinoIcons.arrow_2_circlepath,
          size: 20,
          color: ink,
        );
    }
  }

  Future<void> _onFrostSignPressed(BuildContext context) async {
    final wallet = ref.read(pWallets).getWallet(walletId) as BitcoinFrostWallet;
    ref.read(pFrostScaffoldArgs.state).state = (
      info: (
        walletName: wallet.info.name,
        frostCurrency: wallet.cryptoCurrency,
      ),
      walletId: walletId,
      stepRoutes: FrostRouteGenerator.signFrostTxStepRoutes,
      parentNav: Navigator.of(context),
      frostInterruptionDialogType:
          FrostInterruptionDialogType.transactionCreation,
      callerRouteName: WalletView.routeName,
    );

    await Navigator.of(context).pushNamed(FrostStepScaffold.routeName);
  }

  Future<void> _onExchangePressed(BuildContext context) async {
    final CryptoCurrency coin = ref.read(pWalletCoin(walletId));

    if (coin.network.isTestNet) {
      await showDialog<void>(
        context: context,
        builder: (_) => const StackOkDialog(
          title: "Exchange not available for test net coins",
        ),
      );
    } else {
      Future<Currency?> _future;
      final isar = await ExchangeDataLoadingService.instance.isar;
      try {
        _future = isar.currencies
            .where()
            .tickerEqualToAnyExchangeNameName(coin.ticker)
            .findFirst();
      } catch (_) {
        _future = ExchangeDataLoadingService.instance.loadAll().then(
          (_) => isar.currencies
              .where()
              .tickerEqualToAnyExchangeNameName(coin.ticker)
              .findFirst(),
        );
      }

      final currency = await showLoading(
        whileFuture: _future,
        context: context,
        message: "Loading...",
      );

      if (context.mounted) {
        unawaited(
          Navigator.of(context).pushNamed(
            WalletInitiatedExchangeView.routeName,
            arguments: Tuple2(
              walletId,
              currency == null ? Bitcoin(CryptoCurrencyNetwork.main) : coin,
            ),
          ),
        );
      }
    }
  }

  Future<void> _onBuyPressed(BuildContext context) async {
    final CryptoCurrency coin = ref.read(pWalletCoin(walletId));

    if (coin.network.isTestNet) {
      await showDialog<void>(
        context: context,
        builder: (_) =>
            const StackOkDialog(title: "Buy not available for test net coins"),
      );
    } else {
      if (mounted) {
        unawaited(
          Navigator.of(context).pushNamed(
            BuyInWalletView.routeName,
            arguments: coin.hasBuySupport
                ? coin
                : Bitcoin(CryptoCurrencyNetwork.main),
          ),
        );
      }
    }
  }

  Future<void> attemptAnonymize() async {
    bool shouldPop = false;
    unawaited(
      showDialog(
        context: context,
        builder: (context) => WillPopScope(
          child: const CustomLoadingOverlay(
            message: "Anonymizing balance",
            eventBus: null,
          ),
          onWillPop: () async => shouldPop,
        ),
      ),
    );
    final wallet = ref.read(pWallets).getWallet(walletId);

    final Amount publicBalance = wallet.info.cachedBalance.spendable;
    if (publicBalance <= Amount.zero) {
      shouldPop = true;
      if (mounted) {
        Navigator.of(
          context,
        ).popUntil(ModalRoute.withName(WalletView.routeName));
        unawaited(
          showFloatingFlushBar(
            type: FlushBarType.info,
            message: "No funds available to privatize!",
            context: context,
          ),
        );
      }
      return;
    }

    try {
      if (wallet is MwebInterface && wallet.info.isMwebEnabled) {
        await wallet.anonymizeAllMweb();
      } else {
        await (wallet as FiroWallet).anonymizeAllSpark();
      }
      shouldPop = true;
      if (mounted) {
        Navigator.of(
          context,
        ).popUntil(ModalRoute.withName(WalletView.routeName));
        unawaited(
          showFloatingFlushBar(
            type: FlushBarType.success,
            message: "Privatize transaction submitted",
            context: context,
          ),
        );
      }
    } catch (e) {
      shouldPop = true;
      if (mounted) {
        Navigator.of(
          context,
        ).popUntil(ModalRoute.withName(WalletView.routeName));
        await showDialog<dynamic>(
          context: context,
          builder: (_) => StackOkDialog(
            title: "Privatize all failed",
            message: "Reason: $e",
          ),
        );
      }
    }
  }

